import{_ as t,o as r,c as o,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const _=JSON.parse('{"title":"Ceph Crimson/Seastore Meeting 2023-03-15","description":"","frontmatter":{"title":"Ceph Crimson/Seastore Meeting 2023-03-15","date":"2023-03-15T00:00:00.000Z","updated":"2023-03-16T00:00:00.000Z","tags":["Ceph存储引擎","快照与克隆操作","Blue Store","系统设计与优化","代码审查与验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Crimson_Seastore_Meeting_2023-03-15.md","filePath":"posts/2023/Ceph_Crimson_Seastore_Meeting_2023-03-15.md","lastUpdated":1780459816000}'),l={name:"posts/2023/Ceph_Crimson_Seastore_Meeting_2023-03-15.md"};function i(s,e,n,h,u,d){return r(),o("div",null,[...e[0]||(e[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="会议时间与参与人员" tabindex="-1">会议时间与参与人员 <a class="header-anchor" href="#会议时间与参与人员" aria-label="Permalink to &quot;会议时间与参与人员&quot;">​</a></h4><ul><li><strong>时间</strong>: 由于夏令时调整，会议时间提前一小时。</li><li><strong>参与人员</strong>: 会议中讨论了关于夏令时调整对与会者的影响，确认调整后的时间对所有参与者无影响。</li></ul><h4 id="主要议题与讨论内容" tabindex="-1">主要议题与讨论内容 <a class="header-anchor" href="#主要议题与讨论内容" aria-label="Permalink to &quot;主要议题与讨论内容&quot;">​</a></h4><ul><li><strong>Ceph研发进展</strong>: <ul><li><strong>Crimson存储引擎</strong>: 包括代码审查，优化读取设备分层设计、多核系统调整、Future Store接口调整以及数据覆盖对象的后期读取功能。</li><li><strong>LBA 400 PRS验证</strong>: 正在进行相关验证工作。</li><li><strong>SysStore中的克隆机制设计</strong>: 讨论了克隆操作的设计，特别是快照修剪和快照恢复机制。</li></ul></li><li><strong>快照与克隆操作的详细讨论</strong>: <ul><li><strong>快照恢复</strong>: 讨论了在恢复过程中如何处理读写操作，尤其是优先恢复头对象而不是克隆对象。</li><li><strong>快照修剪</strong>: 强调了支持任意顺序移除快照的重要性，并讨论了避免碎片化的必要性。</li><li><strong>设计建议</strong>: 提出了通过在对象数据处理程序中建立类似链表的结构来处理克隆引用，而不是在onode中处理，以简化复杂性。</li></ul></li><li><strong>Blue Store的研究</strong>: 建议深入研究Blue Store的处理方式，以借鉴其有效的交互设计。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>快照与克隆操作的设计</strong>: 需要进一步考虑和优化，特别是如何处理快照修剪和恢复操作。</li><li><strong>Blue Store的研究</strong>: 建议深入研究Blue Store的处理方式，特别是其交互机制。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>深入研究Blue Store</strong>: 进一步了解Blue Store如何处理快照和克隆操作，特别是其交互机制。</li><li><strong>继续优化设计</strong>: 根据讨论的建议，继续优化快照和克隆操作的设计，确保操作的高效性和避免碎片化。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议中提到了使用中文进行更有效的沟通，建议在必要时使用中文。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>会议讨论了Ceph存储引擎的多个关键技术问题，特别是关于快照和克隆操作的设计。后续将重点研究Blue Store的处理方式，并继续优化相关设计，以确保系统的稳定性和高效性。</p>',13)])])}const c=t(l,[["render",i]]);export{_ as __pageData,c as default};
